 1	//Given two arrays of integers, it returns a single array with all integers merged. 
 2	// [1,5,2,3],[4,3,5]->[1,5,2,3,4,3,5]
 3	
 4	method single(x:array<int>, y:array<int>) returns (b:array<int>) 
 5	requires x.Length > 0
 6	requires y.Length > 0
 7	// ensuring that the new array is the two arrays joined
 8	ensures b[..] == x[..] + y[..]
 9	
10	{
11	    // getting the new array to have the length of the two arrays
12	    b:= new int [x.Length + y.Length];
13	    var i := 0;
14	    // to loop over the final array
15	    var index := 0;
16	    var sumi := x.Length + y.Length;
17	
18	    while (i < x.Length && index < sumi) 
19	    invariant 0 <= i <= x.Length
20	    invariant 0 <= index <= sumi
21	    // making sure all elements up to index and i in both arrays are same 
22	    invariant  b[..index] == x[..i]
23	
24	    {
25	        b[index]:= x[i];
26	        i := i + 1;
27	        index:= index+1;
28	    }
29	
30	    i := 0;
31	
32	    while (i < y.Length && index < sumi)
33	     invariant 0 <= i <= y.Length
34	     invariant 0 <= index <= sumi
35	     // making sure that all elements in x and y are the same as b
36	    {
37	        b[index]:= y[i];
38	        i := i + 1;
39	        index:= index + 1;
40	    }
41	
42	
43	
44	}
45	
46	method Main()
47	{
48	    var a:= new int [4][1,5,2,3];
49	    var b:= new int [3][4,3,5];
50	    var c:= new int [7];
51	    c := single(a,b);
52	    assert c[..] == [1,5,2,3,4,3,5];
53	    //print c[..];
54	
55	}
